    /**
     * §27.4 rule 3: organizations.inOrg(...) reaches the named scope, and leaves the handle it
     * came from alone.
     */
    @Test
    fun `organizations inOrg changes the path`() = runTest {
        val scoped = mount("GET", "/api/v1/organizations/$overrideId", 200, "{\"created_at\": \"2026-08-26T00:00:00Z\", \"id\": \"11111111-1111-4111-8111-111111111111\", \"metadata\": null, \"name\": \"example\", \"slug\": \"example\", \"updated_at\": \"2026-08-26T00:00:00Z\"}")
        val inherited = mount("GET", "/api/v1/organizations/$ORG_ID", 200, "{\"created_at\": \"2026-08-26T00:00:00Z\", \"id\": \"11111111-1111-4111-8111-111111111111\", \"metadata\": null, \"name\": \"example\", \"slug\": \"example\", \"updated_at\": \"2026-08-26T00:00:00Z\"}")
        val handle = client.management().organizations()
        handle.inOrg(overrideId).get()
        handle.get()
        assertEquals(1, scoped.calls(), "the override must reach the named scope")
        assertEquals(1, inherited.calls(), "and must not have mutated the handle it came from")
    }

